1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import {
3	  objectiveRules,
4	  presetRubbings,
5	  presetRubbingTypes,
6	  rubbingTypeOrder,
7	  sourceId,
8	  validateObjectiveRules,
9	  validateSourceAssignment,
10	  validateSourceSites,
11	  type ObjectiveRules,
12	  type RubbingType,
13	  type SourceAssignment,
14	  type SourceSite,
15	} from "@pirate-sea-race/content/objectives";
16	import { nextInt } from "../random.js";
17	
18	/** An integer sub-unit position supplied by the caller; the ledger does not know the map. */
19	export interface Position {
20	  readonly x: number;
21	  readonly y: number;
22	}
23	
24	/**
25	 * The one place a rubbing is (§4): sealed at its source, owned by a player, held in a recovery cache, or reserved for
26	 * one of the two players inside an unresolved duel.
27	 */
28	export type RubbingLocation =
29	  | { readonly kind: "source"; readonly sourceId: string }
30	  | { readonly kind: "player"; readonly playerId: string }
31	  | { readonly kind: "cache"; readonly cacheId: string }
32	  | { readonly kind: "duel"; readonly duelId: string; readonly playerId: string };
33	
34	/** §16's rubbing: its id and type never change; `revision` counts the moves it has made. */
35	export interface LedgerRubbing {
36	  readonly id: string;
37	  readonly type: RubbingType;
38	  readonly location: RubbingLocation;
39	  readonly revision: number;
40	}
41	
42	/** A source and the rubbing sealed there at the start. It is empty once that rubbing has left; nothing respawns. */
43	export interface LedgerSource {
44	  readonly id: string;
45	  readonly island: number;
46	  readonly x: number;
47	  readonly y: number;
48	  readonly type: RubbingType;
49	  readonly rubbingId: string;
50	  /** Sources start locked; the ruin that guards one unlocks it. */
51	  readonly unlocked: boolean;
52	}
53	
54	/** A held interaction: `heldTicks` counts consecutive ticks of holding since `startTick`. */
55	export type LedgerChannel =
56	  | {
57	      readonly kind: "collect";
58	      readonly sourceId: string;
59	      readonly rubbingId: string;
60	      readonly startTick: number;
61	      readonly lastTick: number;
62	      readonly heldTicks: number;
63	    }
64	  | {
65	      readonly kind: "claim";
66	      readonly cacheId: string;
67	      readonly rubbingId: string;
68	      readonly startTick: number;
69	      readonly lastTick: number;
70	      readonly heldTicks: number;
71	    };
72	
73	export type PlayerStatus = "connected" | "disconnected" | "left";
74	
75	export interface LedgerPlayer {
76	  readonly id: string;
77	  readonly gold: number;
78	  readonly status: PlayerStatus;
79	  /** While disconnected: the tick at which the seat reservation expires. Reconnecting never moves it. */
80	  readonly reservationDeadline: number | null;
81	  /** Once left: where rubbings still reserved in an unresolved duel go when that duel settles. */
82	  readonly exit: Position | null;
83	  readonly channel: LedgerChannel | null;
84	  /** Types this player lost and is owed a fresh rumor for (§11), in type order. The rumor system reads it. */
85	  readonly freshRumors: readonly RubbingType[];
86	}
87	
88	/** A recovery cache (§12). It never despawns; it disappears once empty. Its contents are the rubbings located in it. */
89	export interface LedgerCache {
90	  readonly id: string;
91	  readonly x: number;
92	  readonly y: number;
93	  readonly createdTick: number;
94	}
95	
96	/** `fighting` until the result arrives; `choosing` while the winner picks a type; `settled` once committed. */
97	export type DuelPhase = "fighting" | "choosing" | "settled";
98	
99	export interface DuelResultRecord {
100	  readonly outcome: "win" | "draw" | "cancelled";
101	  readonly winner: string | null;
102	  readonly loser: string | null;
103	  /** Decided by leaving the match (quit or reservation expiry) during the fight: the loser for a win, both players for a cancellation. */
104	  readonly forfeit: boolean;
105	  readonly tick: number;
106	}
107	
108	/** What the commit did. It happens once per duel. */
109	export interface DuelSettlement {
110	  readonly tick: number;
111	  readonly stolenRubbingId: string | null;
